/**
 * dsh-ui-session-delete browser half — generated by dsh-ui-suite/scripts/build.mjs.
 *
 * One component per package: the runtime below is the same code every suite
 * package carries, so installing this package alone works, and the component
 * mounts under the same failure boundary as the rest of the suite.
 *
 * Edit src/component.js (or the runtime in dsh-ui-copy/src/core), then rerun
 * the build.
 */

/**
 * dsh-ui-copy runtime — the one place where a component gets its services.
 *
 * The suite exists because a dozen UI plugins used to poll the same document
 * with a dozen MutationObservers, each injecting its own <style> and each
 * guessing whether the shipped DOM had already mounted. This runtime gives them
 * one observer, one frame budget, one style registry and one failure boundary:
 *
 *   - `observe(pass)` registers a DOM pass; every registered pass runs in a
 *     single rAF-throttled sweep, and one crashing pass never stops the rest.
 *   - `style(id, css)` registers a sheet by component id, so a sheet can be
 *     replaced without touching the DOM and no sheet is ever written twice.
 *   - `mount(key, factory)` calls a component factory under `try`/`catch`, so a
 *     host upgrade that removes a slot, or a disabled external bundle, disables
 *     one component instead of the whole suite.
 *   - `option(name, fallback)` reads the config the host half injected, which is
 *     the only channel a browser bundle has: a boot-graph row arrives as
 *     `{ id, url, rev }` and `apply(ctx, config)` always sees an empty config.
 *
 * Component contract — a component is a top-level function in the built bundle:
 *
 *     function dshuiComponent_<key>(rt) {
 *       if (rt.config.enabled === false) return
 *       ...
 *     }
 *
 * Components never touch `window.__ModuleLoader__`, never build their own
 * MutationObserver, and never write a literal colour, radius, gap, size,
 * duration or shadow: those live in `lib/styles/tokens.css` as `--dshui-*`.
 */

/**
 * Build the runtime handed to every component.
 *
 * @param env - `{ ctx, require }` from the bundle factory.
 * @param config - the host half's injected `window.__DSHUI_CONFIG__` object.
 */
function dshuiCreateRuntime(env, config) {
  var ctx = env.ctx
  var load = env.require
  // The token contract lives on `body` (see lib/styles/tokens.css), so a token
  // is read there rather than from the document root.
  var root = document.body !== null ? document.body : document.documentElement
  var suiteConfig = isRecord(config) ? config : {}

  /** Component state: key -> `{ enabled, options }`. */
  var components = Object.create(null)

  /** Every DOM pass registered by an enabled component. */
  var passes = []

  /** Owned cleanups, run by `dispose`. */
  var cleanups = []

  /** A frame has been requested but has not run yet. */
  var scheduled = false

  function isRecord(value) {
    return typeof value === 'object' && value !== null && !Array.isArray(value)
  }

  function merge(base, over) {
    var out = {}
    var key
    for (key in base) if (Object.prototype.hasOwnProperty.call(base, key)) out[key] = base[key]
    for (key in over) if (Object.prototype.hasOwnProperty.call(over, key)) out[key] = over[key]
    return out
  }

  /**
   * A component key as the schema spells it: `session-delete` -> `sessionDelete`.
   *
   * Component ids stay hyphenated (they match `<nn>-<key>.js` and the sheet
   * names), while the host schema uses camelCase field names, so every lookup
   * tries both spellings rather than making each component remember which one
   * its block landed under.
   */
  function schemaKeyOf(key) {
    return String(key).replace(/-([a-z0-9])/g, function (_, letter) {
      return letter.toUpperCase()
    })
  }

  /**
   * The config block for one component.
   *
   * Accepts both shapes a config can arrive in — a flat `{ quota: { … } }` map
   * and the same value nested under `components` — and both spellings, because
   * the host half writes camelCase while components name themselves with
   * hyphens.
   */
  function componentConfig(key) {
    var names = [key, schemaKeyOf(key)]
    var found = null
    for (var index = 0; index < names.length; index += 1) {
      if (isRecord(suiteConfig[names[index]])) {
        found = suiteConfig[names[index]]
        break
      }
    }
    var nestedSource = isRecord(suiteConfig.components) ? suiteConfig.components : null
    var nested = null
    if (nestedSource !== null) {
      for (var position = 0; position < names.length; position += 1) {
        if (isRecord(nestedSource[names[position]])) {
          nested = nestedSource[names[position]]
          break
        }
      }
    }
    return merge(nested || {}, found || {})
  }

  function warn(key, message) {
    console.warn('[ui-copy/' + key + '] ' + message)
  }

  function fail(key, error) {
    console.error('[ui-copy/' + key + ']', error)
  }

  function request() {
    if (scheduled) return
    scheduled = true
    requestAnimationFrame(run)
  }

  function run() {
    scheduled = false
    if (document.body === null) return
    var snapshot = passes.slice()
    for (var index = 0; index < snapshot.length; index += 1) {
      var entry = snapshot[index]
      if (entry === undefined) continue
      try {
        entry.pass()
      } catch (error) {
        fail(entry.key, error)
        var position = passes.indexOf(entry)
        if (position !== -1) passes.splice(position, 1)
      }
    }
  }

  function sheetById(id) {
    return document.head.querySelector('style[data-dshui-sheet="' + String(id).replace(/["\\]/g, '\\$&') + '"]')
  }

  function installStyle(id, css) {
    var existing = sheetById(id)
    if (existing !== null) {
      existing.textContent = css
      return function () {
        if (existing.parentNode !== null) existing.parentNode.removeChild(existing)
      }
    }
    var style = document.createElement('style')
    style.setAttribute('data-dshui-sheet', id)
    style.textContent = css
    document.head.appendChild(style)
    return function () {
      if (style.parentNode !== null) style.parentNode.removeChild(style)
    }
  }

  function requireExternal(name) {
    try {
      return load(name)
    } catch (error) {
      fail('bundle', 'cannot load "' + name + '": ' + String((error && error.message) || error))
      return null
    }
  }

  /** The object handed to one component factory. */
  function componentApi(key, options) {
    return {
      /* ---- identity -------------------------------------------------- */
      key: key,
      ctx: ctx,
      suite: suiteConfig,

      /* ---- configuration --------------------------------------------- */
      /** This component's own block. `enabled` is already honoured by `mount`. */
      config: options,
      option: function (name, fallback) {
        var value = options[name]
        return value === undefined ? fallback : value
      },
      /** Another component's state, for components that depend on a sibling. */
      component: function (other) {
        return components[other] || { enabled: false, options: {} }
      },
      /** The current theme name, read from the same attribute the host themes on. */
      theme: function () {
        return document.body !== null && document.body.hasAttribute('data-ds-dark-theme') ? 'dark' : 'light'
      },

      /* ---- host services --------------------------------------------- */
      /** An external package, or `null` when it is not in this boot graph. */
      require: requireExternal,
      /** Run a host effect, or run the body directly when the seam is absent. */
      effect: function (body, label) {
        try {
          if (ctx && typeof ctx.effect === 'function') return ctx.effect(body, label || key)
        } catch (error) {
          fail(key, error)
          return undefined
        }
        try {
          return body()
        } catch (error) {
          fail(key, error)
          return undefined
        }
      },

      /* ---- document --------------------------------------------------- */
      /** Register a DOM pass; returns an unsubscribe function. */
      observe: function (pass) {
        var entry = { key: key, pass: pass }
        passes.push(entry)
        if (document.body !== null) request()
        return function () {
          var index = passes.indexOf(entry)
          if (index !== -1) passes.splice(index, 1)
        }
      },
      /** Ask for one sweep on the next frame. */
      schedule: request,
      /** Install or replace a sheet scoped to this component. */
      style: function (id, css) {
        return installStyle(key + '/' + id, css)
      },
      /** Current text of one of this component's sheets. */
      styleText: function (id) {
        var style = sheetById(key + '/' + id)
        return style === null ? '' : style.textContent
      },
      /** A token's computed value; components should prefer the CSS variable. */
      token: function (name, fallback) {
        try {
          var scope = document.body !== null ? document.body : root
          var value = getComputedStyle(scope).getPropertyValue(name).trim()
          if (value !== '') return value
        } catch (error) {
          fail(key, error)
        }
        return fallback === undefined ? '' : fallback
      },

      /* ---- diagnostics ------------------------------------------------ */
      log: function (message) {
        console.info('[ui-copy/' + key + '] ' + message)
      },
      warn: function (message) {
        warn(key, message)
      },
      error: function (error) {
        fail(key, error)
      },
    }
  }

  /**
   * Register a component and hand it the runtime.
   *
   * Enabled is the config's `enabled` when it is a boolean and `true` when the
   * profile says nothing, so a component that ships enabled keeps working after
   * an upgrade that adds a sibling and the user turns things off one by one.
   */
  function mount(key, factory) {
    var options = componentConfig(key)
    var record = {
      key: key,
      enabled: options.enabled === false ? false : true,
      options: options,
    }
    components[key] = record
    if (!record.enabled) return
    if (typeof factory !== 'function') {
      warn(key, 'no factory for this component')
      return
    }
    try {
      factory(componentApi(key, options))
    } catch (error) {
      record.enabled = false
      fail(key, error)
    }
  }

  var observer = null
  if (typeof MutationObserver === 'function') {
    observer = new MutationObserver(request)
    var start = function () {
      if (document.body === null) return
      // No `attributes`: React churns attributes constantly, and a component
      // that writes an attribute from a pass would re-enter itself through the
      // observer. Every surface this suite patches is created or replaced as a
      // node, so childList plus characterData is the whole trigger set.
      observer.observe(document.body, { childList: true, subtree: true, characterData: true })
      request()
    }
    if (document.body !== null) start()
    else document.addEventListener('DOMContentLoaded', start, { once: true })
    cleanups.push(function () {
      observer.disconnect()
    })
  }

  /** Remove every pass, sheet and observer this runtime owns. */
  function dispose() {
    passes.length = 0
    for (var index = 0; index < cleanups.length; index += 1) {
      try {
        cleanups[index]()
      } catch (error) {
        /* a failed cleanup must not stop the rest */
      }
    }
    cleanups.length = 0
  }

  var base = componentApi('runtime', {})
  return {
    ctx: ctx,
    config: suiteConfig,
    require: requireExternal,
    mount: mount,
    component: base.component,
    observe: base.observe,
    schedule: base.schedule,
    style: base.style,
    token: base.token,
    theme: base.theme,
    dispose: dispose,
  }
}

/* ---- component -------------------------------------------------------- */

/**
 * Session deletion: a "Delete session" row in the session row's "…" menu, plus
 * the confirmation dialog that answers it.
 *
 * Why the menu slot instead of DOM work: ui-workspace declares its session-row
 * actions as slot entries — the shipped Pin, Rename, Fork and Archive entries
 * are registered exactly the way a plugin's are — so this component registers
 * into `sidebar.workspaces.session.menu.item` with an order after Archive (400)
 * and inherits the menu's styling, keyboard walk and positioning. The entry
 * receives the row identity (`sessionId`, `displayTitle`) and nothing else; it
 * reads no other component's DOM.
 *
 * Why the clip is a dialog and not a native confirm: deletion is permanent, so
 * the sentence that says so belongs in the host's own surface. The dialog is a
 * `shell.overlay` entry driven by this component's snapshot store, the same
 * shape the shipped archive confirmation uses.
 *
 * After the Host removes the log, `ctx.sessions.refresh()` re-pulls the Session
 * baseline, so the row disappears without a page reload.
 */
function dshuiComponent_session_delete(rt) {
  const React = rt.require('react')
  if (React === null) {
    rt.warn('react is not in this boot graph; session-delete skipped')
    return
  }
  const h = React.createElement

  /**
   * Both surfaces are built from primitives: the menu row is a
   * `MenuItemButton` and the clip is a `Modal`, and the pending request lives in
   * a snapshot store that React subscribes to. There is no plain-DOM rendering
   * of either, so degradation is "no surfaces at all": the menu row is not
   * registered, so nothing offers an action whose confirmation cannot be drawn,
   * and the component logs once and stays inert. A partial registration (row
   * without dialog, a disabled row) would be worse than its absence: the row is
   * the only discoverable affordance, and a dead one reads as a broken menu.
   */
  const store = rt.require('@deepseek-ai/dsh-client-store')
  const primitives = rt.require('@deepseek-ai/dsh-client-ui-primitives')
  if (store === null || typeof store.createSnapshotStore !== 'function' || primitives === null) {
    rt.warn('client store or ui primitives are not in this boot graph; session-delete offers no surfaces')
    return
  }
  const createSnapshotStore = store.createSnapshotStore

  /** Locale namespace for this component's copy; also the slot registrations' `locale`. */
  const NS = 'session-delete'

  /**
   * Host route that performs the deletion.
   *
   * The suite namespaces its host routes, so the old standalone spelling is now
   * an alias: the host half registers both paths against the same handler, which
   * keeps a page cached from before the migration working.
   */
  const DELETE_ROUTE = '/dsh-ui-copy/session-delete/delete'

  /** Copy, in the shape `ctx.locale.register` takes. */
  const zh = {
    'menu.delete': '删除会话',
    'confirm.title': '删除会话',
    'confirm.desc': '将彻底删除「{title}」的会话记录，包括它的子代理会话，并从工作区里移除。此操作不可恢复。',
    'confirm.action': '删除',
    'confirm.pending': '正在删除…',
    'cancel': '取消',
    'close': '关闭',
    'failed.unknown': '这个会话已经不在磁盘上了。',
    'failed.refused': '本机拒绝了这次请求。',
    'failed.partial': '部分数据未能删除，请重试或检查文件权限。',
    'failed.generic': '删除失败，请重试。',
  }
  const en = {
    'menu.delete': 'Delete session',
    'confirm.title': 'Delete session',
    'confirm.desc': 'This permanently deletes “{title}” — including its subagent sessions — and removes it from the workspace. It cannot be undone.',
    'confirm.action': 'Delete',
    'confirm.pending': 'Deleting…',
    'cancel': 'Cancel',
    'close': 'Close',
    'failed.unknown': 'This session is no longer on disk.',
    'failed.refused': 'This machine refused the request.',
    'failed.partial': 'Part of the data could not be removed. Retry, or check file permissions.',
    'failed.generic': 'Deletion failed. Try again.',
  }

  /** Stylesheet for the confirm dialog's one component-owned accent. */
  const STYLESHEET = `
.duic-session-delete-danger { color: var(--dshui-danger, currentColor); }
.duic-session-delete-body { display: flex; flex-direction: column; gap: var(--dshui-space-4); }
.duic-session-delete-note { color: var(--dshui-text-tertiary); font-size: var(--dshui-text-size-sm); line-height: var(--dshui-line-normal); }
.duic-session-delete-status { color: var(--dshui-text-secondary, currentColor); font-size: var(--dshui-text-size-sm); line-height: var(--dshui-line-normal); }
.duic-session-delete-error { color: var(--dshui-danger, currentColor); font-size: var(--dshui-text-size-sm); line-height: var(--dshui-line-normal); }
`

  /** The pending confirmation: `{ sessionId, displayTitle }`, or `null` when closed. */
  const requestStore = createSnapshotStore(null)

  /** One reason phrase per Host refusal. */
  function messageFor(payload, t) {
    const reason = payload !== null && typeof payload === 'object' ? payload.reason : undefined
    if (reason === 'unknown') return t('failed.unknown')
    if (reason === 'refused' || reason === 'invalid-id' || reason === 'bad-request') return t('failed.refused')
    if (reason === 'unlink-failed' || reason === 'failed') return t('failed.partial')
    return t('failed.generic')
  }

  /**
   * Subscribe one component to the pending-confirmation store.
   *
   * @returns the current request, or `null`.
   */
  function useRequest() {
    return React.useSyncExternalStore(requestStore.subscribe, requestStore.getSnapshot)
  }

  /**
   * One menu row.
   *
   * The row closes the menu before asking, so the dialog it opens is not
   * stacked behind an open menu layer.
   *
   * @param props - the row identity, the menu's open-state hook, and the
   *   component's request callback.
   * @returns the menu item.
   */
  function DeleteSessionMenuItem({ sessionId, displayTitle, useMenuOpenState, requestDelete, t }) {
    const [, setMenuOpen] = useMenuOpenState()
    return h(
      primitives.MenuItemButton,
      {
        separatorBefore: true,
        icon: h(primitives.IconTrashOutlineRegular, { size: 14 }),
        onSelect: () => {
          setMenuOpen(false)
          requestDelete(sessionId, displayTitle)
        },
      },
      t('menu.delete'),
    )
  }

  /**
   * The confirmation dialog.
   *
   * @param props - the pending request, the deletion hop, its settlement, and
   *   the locale seat.
   * @returns the open dialog, or `null`.
   */
  function DeleteConfirmDialog({ performDelete, settleDelete, t }) {
    const request = useRequest()
    if (request === null) return null
    return h(DeleteConfirmForm, { request, performDelete, settleDelete, t }, request.sessionId)
  }

  /** One request's dialog; its in-flight and error state die with it. */
  function DeleteConfirmForm({ request, performDelete, settleDelete, t }) {
    const [deleting, setDeleting] = React.useState(false)
    const [error, setError] = React.useState(null)

    const close = () => {
      if (deleting) return
      settleDelete()
    }

    const confirm = () => {
      setDeleting(true)
      setError(null)
      performDelete(request.sessionId)
        .then(() => {
          setDeleting(false)
          settleDelete()
        })
        .catch((reason) => {
          setDeleting(false)
          setError(reason instanceof Error ? reason.message : String(reason))
        })
    }

    return h(
      primitives.Modal,
      {
        open: true,
        onClose: close,
        closeLabel: t('close'),
        title: t('confirm.title'),
        description: t('confirm.desc', { title: request.displayTitle }),
        footer: h(React.Fragment, null, [
          h(primitives.Button, { variant: 'outline', disabled: deleting, onClick: close, key: 'cancel' }, t('cancel')),
          h(
            primitives.Button,
            { variant: 'outline', className: 'duic-session-delete-danger', disabled: deleting, onClick: confirm, key: 'confirm' },
            t('confirm.action'),
          ),
        ]),
      },
      h('div', { className: 'duic-session-delete-body' }, [
        deleting ? h('div', { className: 'duic-session-delete-status', role: 'status', key: 'status' }, t('confirm.pending')) : null,
        error !== null ? h('div', { className: 'duic-session-delete-error', role: 'alert', key: 'error' }, error) : null,
      ]),
    )
  }

  /**
   * Install both surfaces.
   *
   * The component waits for the Session controller alongside the slot service,
   * because the refresh that makes the deleted row disappear is part of the
   * operation rather than an afterthought.
   *
   * @param ctx - client root context.
   */
  function install(ctx) {
    // Every surface below needs the slot registry, the locale dictionaries and
    // the Session controller, so the body runs inside one service scope instead
    // of touching those services off the root context — reading an uninjected
    // service throws in this host, which is what silently killed both surfaces.
    ctx.inject(['slots', 'locale', 'sessions'], (scope) => {
    scope.effect(() => scope.locale.register(NS, { zh, en }), 'ui-copy/session-delete: dictionaries')

    // The dialog's accent lives in the suite's sheet registry, so switching the
    // component off removes these rules with it instead of leaving them behind;
    // the effect keeps the sheet's lifetime tied to this context, the way the
    // standalone plugin's own `<style>` was.
    rt.effect(() => rt.style('confirm', STYLESHEET), 'ui-copy/session-delete: stylesheet')

    /** Open the confirmation for one row. */
    const requestDelete = (sessionId, displayTitle) => {
      requestStore.set({ sessionId, displayTitle })
    }

    /** Close the confirmation without deleting. */
    const settleDelete = () => {
      requestStore.set(null)
    }

    /**
     * Delete one session through the Host, then re-pull the Session baseline.
     *
     * @param sessionId - the session to delete.
     * @returns resolution once the Host removed it and the list caught up.
     * @throws when the Host refused or the request itself failed.
     */
    const performDelete = async (sessionId) => {
      const bind = scope.locale.bind(NS)
      let response
      try {
        response = await fetch(DELETE_ROUTE, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ sessionId }),
          credentials: 'same-origin',
        })
      } catch {
        throw new Error(bind('failed.generic'))
      }

      let payload = null
      try {
        payload = await response.json()
      } catch {
        // A body-less failure keeps its status-only verdict below.
      }

      if (!response.ok || payload === null || payload.ok !== true) {
        throw new Error(messageFor(payload, bind))
      }

      await scope.sessions.refresh()
      return payload
    }

    scope.slots.inject('sidebar.workspaces.session.menu.item', () => scope.slots.register({
      name: 'sidebar.workspaces.session.menu.item',
      id: 'dsh-session-delete.menu',
      order: 500,
      locale: NS,
      inject: () => ({ requestDelete }),
    }, DeleteSessionMenuItem))

    scope.slots.inject('shell.overlay', () => scope.slots.register({
      name: 'shell.overlay',
      id: 'dsh-session-delete.confirm',
      locale: NS,
      inject: () => ({ performDelete, settleDelete }),
    }, DeleteConfirmDialog))
    })
  }

  install(rt.ctx)
}

/* ---- entry ------------------------------------------------------------ */

window.__ModuleLoader__.load({
  // The boot-graph row id is the package name; client-modules serves this file
  // at `/plugins/<包名>/client.js` and keys the factory by the same string.
  id: 'dsh-ui-session-delete',
  factory: (require) => {
    const module = { exports: {} }
    const exports = module.exports
    Object.defineProperty(exports, Symbol.toStringTag, { value: 'Module' })

    /**
     * Mount this package's component on its own runtime.
     *
     * The host half injects this row's configuration as `window.DSHUI_SESSION_DELETE`
     * before the boot graph runs, because a boot-graph row arrives as
     * `{ id, url, rev }` and `apply(ctx, config)` always sees an empty config.
     */
    function apply(ctx) {
      const injected = window.DSHUI_SESSION_DELETE
      const config = typeof injected === 'object' && injected !== null ? injected : {}
      const runtime = dshuiCreateRuntime({ ctx, require }, { 'session-delete': config })
      runtime.mount('session-delete', dshuiComponent_session_delete)
      exports.runtime = runtime
      return function dispose() {
        runtime.dispose()
      }
    }

    exports.apply = apply
    exports.inject = []
    return module.exports
  },
})
